# ---------- shared blocks ----------
def why_choose(root, title='Why Choose MYSense?', lbl='Why Us'):
    items=[('Multi-industry expertise','We’ve successfully delivered digital growth for Healthcare, Automotive, FMCG and Finance. Your strategy will be built from proven frameworks.'),
           ('Tailor-made strategies','We don’t adopt one-size-fits-all. Your brand gets a custom roadmap keyed to your specialties and target audience.'),
           ('Strategic and data-driven','We prioritise initiatives based on impact and ROI, leverage market trends and competitor analysis, and continuously A/B test to optimise campaigns and processes.'),
           ('Dedicated account team','A full team managing your brand daily: project manager, strategists, designers and ads specialists supporting your growth.')]
    cards=''.join(f'<div class="stat-card rv" style="min-height:300px"><p class="t-19">{esc(t)}</p><p class="stat-card__d" style="padding-top:40px">{esc(d)}</p></div>' for t,d in items)
    return section(G.head_stack(lbl,title,maxw=620)+f'<div class="stat-grid" data-stagger="0.08">{cards}</div>')

def pains(root, lbl, title, items, sub=None):
    cards=''.join(f'<div class="stat-card rv" style="min-height:280px"><div class="stat-card__v"><em>{i+1:02d}</em></div><p class="t-19" style="margin-top:14px">{esc(t)}</p>'+(f'<p class="stat-card__d" style="padding-top:30px">{esc(d)}</p>' if d else '')+'</div>' for i,(t,d) in enumerate(items))
    return section(G.head_stack(lbl,title,sub,maxw=760)+f'<div class="stat-grid cols-{min(4,len(items))}" data-stagger="0.08">{cards}</div>')

def rows(items, root, lbl, title, sub=None, href_map=None):
    out=''.join(f'<a class="frow rv" href="{root+(h.lstrip("/")) if h else "#general-form"}"><span class="t-19">{esc(t)}</span><span class="d">{esc(d)}</span><span class="sq">{ARROW_NE}</span></a>' for t,d,h in items)
    return section(G.head_stack(lbl,title,sub,maxw=760)+f'<div class="feature-rows" data-stagger="0.05">{out}</div>')

POOL=['assets/img/team/life-5.webp','assets/img/team/life-7.webp','assets/img/misc/team-meeting.webp','assets/img/team/life-6.webp','assets/img/team/life-2.webp','assets/img/team/life-9.webp','assets/img/team/life-10.webp','assets/img/team/life-3.webp','assets/img/misc/mysense-photo.jpg','assets/img/team/life-4.webp','assets/img/team/life-11.webp','assets/img/brand/award-stage.webp','assets/img/team/life-1.webp']
_pick={'n':0}
def pick_image(key):
    import zlib
    return POOL[zlib.crc32(key.encode())%len(POOL)]
def process_section(root, lbl, title, steps_, image=None, card_title='MYSense', card_sub='Our Working Process'):
    image = image or pick_image(title)
    return section(G.head_stack(lbl,title,maxw=733)+f'''<div class="process"><div class="process__img rv"><img src="{root}{image}" alt="" loading="lazy"><p class="t-h2">{esc(card_title)}</p><div><p class="t-tiny">300+ brands served</p><p class="t-19" style="margin-top:10px">{esc(card_sub)}</p></div></div>{steps(steps_)}</div>''')

def panel_section(root, lbl, title, items):
    return section(f'<div class="panel rv">{G.head_stack(lbl,title,light=True,maxw=700)}{accordion(items,root)}</div>','section section--tight')

def cases_section(root, cat=None, n=2, title='Be One Of Our Success Stories', lbl='Case Studies', sub='Join brands that have already transitioned to data-driven growth.'):
    cs=[c for c in G.CASES if (cat is None or c['cat']==cat)][:n]
    if not cs: return ''
    return section(G.head_split(lbl,title,sub,display=False)+f'<div class="case-grid">{"".join(case_card(c,root) for c in cs)}</div>')

def closing(title, text, btn_text, href, root):
    return cta_panel(title, text, btn_text, href, root)

def hero_inner(root, lbl, h1, sub, btn_text='Get a Free Consultation', href='#general-form', stats=None, display=False):
    st=''
    if stats:
        st='<div class="about-stats" style="margin-top:70px"><div class="stat-grid" data-stagger="0.08">'+''.join(stat_card(v,s,l,short=True,pre=p) for p,v,s,l in stats)+'</div></div>'
    cls='t-display' if display else 't-h1'
    return f'''<section class="page-hero"><div class="wrap"><div class="rv-hero d1">{label(lbl)}</div>
<div class="page-hero__row" style="margin-top:32px"><div><h1 class="{cls} rv-hero d2" style="text-transform:none;max-width:860px">{h1}</h1><p class="t-19 page-hero__sub rv-hero d3">{sub}</p></div><div class="rv-hero d3">{btn(btn_text,href if href.startswith('#') else root+href.lstrip('/'))}</div></div>{st}</div></section>'''

CONTACT_BG='assets/img/misc/mysense-photo.jpg'
def band(root, title='Talk To Us', text=None):
    return contact_band(root, CONTACT_BG, title=title, text=text, direct_btn=('Let’s Talk Now!','https://wa.me/60193541688'))

