def service_page(s):
    def b(root):
        out=hero_inner(root,s['lbl'],s['title'],s['sub'],s['btn'],'#general-form',stats=s.get('stats'))
        if s.get('pains'): out+=pains(root,'Why It Matters',s['pains'][0],s['pains'][1])
        if s.get('panel'): out+=panel_section(root,'What We Do',s['panel'][0],s['panel'][1])
        out+=process_section(root,'Process',s['steps_title'],s['steps'],card_sub=s['steps_title'])
        if s.get('platforms'):
            tiles=''.join(f'<div class="stat-card rv" style="min-height:260px"><p class="t-19">{esc(t)}</p><p class="stat-card__d" style="padding-top:30px">{esc(d)}</p></div>' for t,d in s['platforms'])
            out+=section(G.head_stack('Platforms','Platforms We Use to Maximise Your Brand Exposure',maxw=700)+f'<div class="stat-grid cols-3" data-stagger="0.08">{tiles}</div>')
        if s.get('cat'): out+=cases_section(root,s['cat'],2)
        if s.get('gallery'): out+=section(G.head_split('Case Studies','Successful Case Studies','Social media results for Malaysian brands.',display=False)+'<div class="case-grid" style="margin-top:70px">'+''.join(f'<img class="rv" src="{root}{g}" alt="" loading="lazy" style="border-radius:6px;width:100%">' for g in s['gallery'])+'</div>')
        if s.get('tags'): out+=section(G.head_stack('Showcase','Successful Case Studies',maxw=600)+'<div class="tag-row rv">'+''.join(f'<span class="tag">{esc(t)}</span>' for t in s['tags'])+'</div>')
        out+=why_choose(root)
        out+=G.faq_section(root,s['faq'])
        out+=closing(s['closing'][0],s['closing'][1],s['closing'][2],'/contact/',root)
        out+=band(root)
        return out
    return b

