def industry_page(d):
    def b(root):
        out=hero_inner(root,'We Work With · '+d['nav'],d['title'],d['sub'],'Free Marketing Strategy Call','#general-form')
        img=IND_IMG.get(d['slug'])
        if img: out=out.replace('</div></section>',f'<div class="ind-img rv"><img src="{root}{img}" alt="{esc(d["nav"])}" loading="lazy"></div></div></section>',1)
        out+=pains(root,'Common Challenges',f'Common Challenges {d["nav"]} Businesses Face',d['challenges'])
        if d.get('funnel'): out+=process_section(root,'Approach',f'A Structured Approach to {d["nav"]} Growth',d['funnel'],card_sub='Awareness → Consideration → Conversion')
        out+=rows(SOLUTIONS,root,'Solutions','MYSense Digital Marketing Solutions','We understand the balance between accuracy, compliance, and performance, ensuring your campaigns are both effective and aligned with regulations.')
        if d.get('segments'):
            out+=section(G.head_stack('Segments','Healthcare Segments We Support',maxw=600)+'<div class="tag-row rv">'+''.join(f'<span class="tag">{esc(t)}</span>' for t in d['segments'])+'</div>')
        plats=d.get('platforms') or CHANNELS
        tiles=''.join(f'<div class="stat-card rv" style="min-height:260px"><p class="t-19">{esc(t)}</p><p class="stat-card__d" style="padding-top:30px">{esc(x)}</p></div>' for t,x in plats)
        out+=section(G.head_stack('Channels','Perfect Marketing Channel for Your Business!',maxw=700)+f'<div class="stat-grid cols-{len(plats)}" data-stagger="0.08">{tiles}</div>')
        if d.get('ways'):
            out+=section(f'<div class="panel rv">{G.head_stack("Best Ways","Best Ways to Use Digital Marketing for "+d["nav"]+" to Boost Sales",light=True,maxw=760)}<ul class="plan__feats" style="color:var(--g-300)">'+''.join(f'<li>{PLUS}{esc(w)}</li>' for w in d['ways'])+'</ul></div>','section section--tight')
        out+=cases_section(root,d['cat'],2)
        out+=why_choose(root,'Why Brands Work with MYSense')
        out+=closing(d['closing'][0],d['closing'][1],'Free Digital Marketing Strategy Call','/contact/',root)
        out+=band(root)
        return out
    return b

