        out+=pains(root,'SEO Services',f'SEO Services for {c} Businesses',[('On-Page SEO',f'We optimise your website’s pages for the right {L["short"]}-focused keywords, improve titles, meta descriptions, headings, internal links and content structure.'),('Technical SEO','We identify and fix technical issues that slow down or block your SEO performance, such as crawl errors, slow loading pages, mobile responsiveness and indexing gaps.'),(f'Local SEO for {c}',f'We optimise your Google Business Profile, local citations and location-based landing pages so your business appears in “near me” and {c}-specific searches.'),('Content & Keyword Strategy',f'We research high-traffic, high-intent keywords that your {L["short"]} audience is actually searching for, then plan content around them.')])
