    write('/industries/','Industries We Work With | MYSense','Digital marketing for healthcare, automotive, finance, beauty, home improvement, education, F&B, B2B and fashion brands in Malaysia.',industries_index)
    for d in INDUSTRIES: write(f'/industries/{d["slug"]}/',f'{d["nav"]} Digital Marketing Agency Malaysia | MYSense',d['sub'][:155],industry_page(d))
    for L in LOCS: write(f'/{L["slug"]}/',f'SEO {L["city"]} | SEO Agency & Digital Marketing | MYSense',L['sub'][:155],location_page(L))
